import os, base64

data = {
    'Əhalinin_sayı__ilin_əvvəlinə__20261015140255.csv': '...',
    'İqtisadiyyatın_sahələri_üzrə_orta_aylıq_nominal_əməkhaqqı__manat__20261015135923.csv': '...',
    'İstehlak_qiymətləri_indeksi__əvvəlki_ilə_nisbətən__faizlə__20261015140019.csv': '...',
    'Sənaye_sahəsində_muzdla_işləyənlərin_iqtisadi_rayonlar_və_inzibati_ərazi_vahidləri_üzrə_orta_aylıq_nominal_əməkhaqqı__manat_20261015135529.csv': '...',
    'dataset0.doc': '>...'
}

os.makedirs('data/raw', exist_ok=True)

for name, content in data.items():
    filepath = os.path.join('data', 'raw', name)
    with open(filepath, 'wb') as f:
        f.write(base64.b64decode(content))
    print(f"Yükləndi: {filepath}")
